create or replace view public.test_lab_stock_overview with (security_invoker=true) as select p.id product_id,p.operation,p.name,p.category,p.variant_label,p.cost_price,p.sale_price,p.active,coalesce(s.quantity,0)::integer physical_quantity,coalesce(r.reserved_quantity,0)::integer reserved_quantity,greatest(coalesce(s.quantity,0)-coalesce(r.reserved_quantity,0),0)::integer available_quantity,coalesce(i.incoming_quantity,0)::integer incoming_quantity from public.test_lab_products p left join public.test_lab_stock s on s.product_id=p.id left join lateral(select coalesce(sum(quantity_reserved),0)::integer reserved_quantity from public.test_lab_reservations rr where rr.product_id=p.id and rr.status in ('reserved','partial')) r on true left join lateral(select coalesce(sum(x.quantity_ordered-x.quantity_received),0)::integer incoming_quantity from public.test_lab_purchase_order_items x join public.test_lab_purchase_orders o on o.id=x.purchase_order_id where x.product_id=p.id and o.status in ('pending','partial')) i on true;
create or replace view public.test_lab_sales_overview with (security_invoker=true) as select s.id,s.operation,s.customer_id,c.name customer_name,s.quoted_on,s.general_status,s.payment_status,s.delivery_status,s.total_cost,s.total_amount,s.total_profit,s.notes,s.created_at,s.updated_at,coalesce(items.product_summary,'') product_summary,coalesce(items.total_items,0)::integer total_items,coalesce(res.reservation_status,case when s.delivery_status='delivered' then 'fulfilled' else null end) reservation_status from public.test_lab_sales s join public.test_lab_customers c on c.id=s.customer_id left join lateral(select string_agg(p.name||coalesce(' · '||p.variant_label,'')||' ×'||si.quantity,', ' order by p.name) product_summary,sum(si.quantity)::integer total_items from public.test_lab_sale_items si join public.test_lab_products p on p.id=si.product_id where si.sale_id=s.id) items on true left join lateral(select case when bool_and(r.status='fulfilled') then 'fulfilled' when bool_or(r.status='awaiting_stock') then 'awaiting_stock' when bool_or(r.status='partial') then 'partial' when bool_and(r.status='reserved') then 'reserved' when bool_and(r.status='cancelled') then 'cancelled' else null end reservation_status from public.test_lab_reservations r where r.sale_id=s.id) res on true;
create or replace view public.test_lab_purchase_orders_overview with (security_invoker=true) as select o.id,o.operation,o.supplier_id,s.name supplier_name,o.ordered_on,o.status,o.created_at,o.updated_at,coalesce(x.item_count,0)::integer item_count,coalesce(x.ordered_units,0)::integer ordered_units,coalesce(x.received_units,0)::integer received_units,coalesce(x.pending_units,0)::integer pending_units,coalesce(x.order_total,0)::numeric(12,2) order_total,coalesce(x.product_summary,'') product_summary from public.test_lab_purchase_orders o join public.test_lab_suppliers s on s.id=o.supplier_id left join lateral(select count(*)::integer item_count,sum(i.quantity_ordered)::integer ordered_units,sum(i.quantity_received)::integer received_units,sum(i.quantity_ordered-i.quantity_received)::integer pending_units,sum(i.quantity_ordered*i.unit_cost)::numeric(12,2) order_total,string_agg(p.name||' ×'||i.quantity_ordered,', ' order by p.name) product_summary from public.test_lab_purchase_order_items i join public.test_lab_products p on p.id=i.product_id where i.purchase_order_id=o.id) x on true;
create or replace view public.test_lab_dashboard_summary with (security_invoker=true) as select op.operation,(select count(*)::integer from public.test_lab_products p where p.operation=op.operation and p.active) product_count,(select coalesce(sum(v.physical_quantity),0)::integer from public.test_lab_stock_overview v where v.operation=op.operation) physical_units,(select coalesce(sum(v.reserved_quantity),0)::integer from public.test_lab_stock_overview v where v.operation=op.operation) reserved_units,(select coalesce(sum(v.available_quantity),0)::integer from public.test_lab_stock_overview v where v.operation=op.operation) available_units,(select coalesce(sum(v.incoming_quantity),0)::integer from public.test_lab_stock_overview v where v.operation=op.operation) incoming_units,(select count(*)::integer from public.test_lab_sales s where s.operation=op.operation and s.general_status<>'cancelled') sales_count,(select count(*)::integer from public.test_lab_sales s where s.operation=op.operation and s.general_status<>'cancelled' and s.payment_status='receivable') pending_payment_count,(select count(*)::integer from public.test_lab_sales s where s.operation=op.operation and s.general_status<>'cancelled' and s.delivery_status='to_deliver') pending_delivery_count,(select coalesce(sum(s.total_amount),0)::numeric(12,2) from public.test_lab_sales s where s.operation=op.operation and s.general_status<>'cancelled') revenue,(select coalesce(sum(s.total_profit),0)::numeric(12,2) from public.test_lab_sales s where s.operation=op.operation and s.general_status<>'cancelled') profit,(select count(*)::integer from public.test_lab_purchase_orders o where o.operation=op.operation and o.status in ('pending','partial')) open_orders from (values('supplements'::text),('fitness'::text)) op(operation);
grant select on public.test_lab_stock_overview,public.test_lab_sales_overview,public.test_lab_purchase_orders_overview,public.test_lab_dashboard_summary to authenticated;
